<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Http\Requests\Admin\StoreStaffRequest;
use App\Http\Requests\Admin\UpdateStaffRequest;
use App\Models\User;
use App\Services\AuditLogger;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\View\View;

class AdminUserController extends Controller
{
    public function index(Request $request): View { $users=User::withTrashed()->withCount(['residentReports','assignedReports'])->when($request->q,fn($q,$v)=>$q->where(fn($s)=>$s->where('first_name','like',"%$v%")->orWhere('last_name','like',"%$v%")->orWhere('email','like',"%$v%")->orWhere('phone_number','like',"%$v%")))->when($request->role,fn($q,$v)=>$q->where('role',$v))->when($request->status,fn($q,$v)=>$q->where('status',$v))->orderBy('last_name')->paginate(15)->withQueryString(); return view('admin.users.index',compact('users')); }
    public function storeStaff(StoreStaffRequest $request, AuditLogger $audit) { $user=DB::transaction(function()use($request,$audit){$data=$request->validated();unset($data['password_confirmation']);$user=User::create([...$data,'email'=>mb_strtolower($data['email']),'email_verified_at'=>now(),'role'=>'staff','must_change_password'=>true,'created_by'=>auth()->id()]);$audit->log('staff.created',$user,'Staff account created.',[],['email'=>$user->email,'role'=>'staff','status'=>$user->status]);return $user;}); return back()->with('success',"Staff account for {$user->email} created successfully."); }
    public function status(Request $request, User $user, AuditLogger $audit) { $data=$request->validate(['status'=>['required','in:active,inactive,suspended']]); abort_if($user->is(auth()->user()),422,'You cannot change your own account status.'); if($user->role==='admin' && $data['status']!=='active') abort_if(User::where('role','admin')->where('status','active')->count()<=1,422,'The last active administrator cannot be disabled.'); $old=$user->status; DB::transaction(fn()=>[$user->update($data),$audit->log('user.status_changed',$user,'User account status changed.',['status'=>$old],$data)]); return back()->with('success','Account status updated successfully.'); }
    public function update(UpdateStaffRequest $request, User $user, AuditLogger $audit) { $data=$request->validated(); abort_if($user->is(auth()->user()) && $data['role']!==$user->role,422,'You cannot change your own account role.'); abort_if($user->role==='admin' && $user->status==='active' && $data['role']!=='admin' && User::where('role','admin')->where('status','active')->count()<=1,422,'The last active administrator cannot be demoted.'); unset($data['password_confirmation']); if(empty($data['password'])) unset($data['password']); $data['email']=mb_strtolower($data['email']); $fields=['first_name','middle_name','last_name','suffix','email','phone_number','role','position','department']; $old=$user->only($fields); DB::transaction(function()use($user,$data,$old,$fields,$audit){$user->update($data);$audit->log('user.updated',$user,'User account details updated.',$old,$user->only($fields));}); return back()->with('success','Account details for '.$user->email.' updated successfully.'); }
    public function destroy(Request $request, User $user, AuditLogger $audit) { abort_if($user->is(auth()->user()),422,'You cannot delete your own account.'); abort_if($user->role==='admin' && $user->status==='active' && User::where('role','admin')->where('status','active')->count()<=1,422,'The last active administrator cannot be deleted.'); $email=$user->email; DB::transaction(function()use($user,$audit){$user->delete();$audit->log('user.deleted',$user,'User account deleted.',['email'=>$user->email,'role'=>$user->role,'status'=>$user->status],[]);}); return back()->with('success',"Account for {$email} deleted successfully."); }
    public function restore(Request $request, int $userId, AuditLogger $audit) { $user=User::withTrashed()->findOrFail($userId); abort_unless($user->trashed(),422,'This account is not deleted.'); DB::transaction(function()use($user,$audit){$user->restore();$audit->log('user.restored',$user,'User account restored.',['email'=>$user->email,'role'=>$user->role,'status'=>$user->status],[]);}); return back()->with('success',"Account for {$user->email} restored successfully."); }
}
